import { Component, EventEmitter, Input, Output } from '@angular/core';
import { IconComponent } from '../../icon/icon.component';
import { toolEvents } from '../../../../pdf/interfaces/pdf.interface';

@Component({
  selector: 'weblink',
  standalone: true,
  imports: [IconComponent],
  templateUrl: './weblinktable.component.html',
  styleUrl: './weblinktable.component.scss'
})
export class WeblinktableComponent {
  @Input() wlink: any = []
  @Output() viewlink: EventEmitter<toolEvents> = new EventEmitter();

  viewUrl(x) {
    const url = x.cUrl; // Replace with the URL you want to open
    window.open(url, '_blank');
  }

  gotoPage(x, page) {
    if (page.length > 2 && page.split('-').length > 1) {
      page = page.split('-')[0]
    }
    this.viewlink.emit({ event: 'VIEW-RESULT', data: { nBundledetailid: x.nBundledetailid, page: page } })

  }
}
