import { Component, EventEmitter, Input, Output } from '@angular/core';
import { IconComponent } from '../../icon/icon.component';
import { BadgeComponent } from '../../badge/badge.component';
import { CommonModule } from '@angular/common';
import { I } from '@angular/cdk/keycodes';
import { toolEvents } from '../../../../pdf/interfaces/pdf.interface';
import { TabletruncComponent } from '../tabletrunc/tabletrunc.component';

@Component({
  selector: 'factlink',
  standalone: true,
  imports: [IconComponent, BadgeComponent, CommonModule, TabletruncComponent],
  templateUrl: './factlinktable.component.html',
  styleUrl: './factlinktable.component.scss'
})
export class FactlinktableComponent {
  // factlist: any;
  @Input() linkview: string;
  @Input() dlink: any = []
  @Input() flink: any = []
  @Output() viewlink: EventEmitter<toolEvents> = new EventEmitter();
  @Output() viewFile: EventEmitter<string> = new EventEmitter();

  constructor() { }

  ngOnInit(): void {
    //Called after the constructor, initializing input properties, and the first call to ngOnChanges.
    //Add 'implements OnInit' to the class.
  }


  gotoPage(x, page) {
    debugger  
    // if (page.length > 2 && page.split('-').length > 1) {
    //   page = page.split('-')[0]
    // }
    this.viewlink.emit({ event: 'VIEW-LINK-RESULT', data: { nBundledetailid: x.nBundledetailid, page: page } })

  }


  navigateToFactPage(page) {
    this.viewFile.emit('VIEW_' + page)
  }

}
