import { ScrollingModule } from '@angular/cdk/scrolling';
import { CommonModule } from '@angular/common';
import { ChangeDetectorRef, Component, EventEmitter, Input, OnChanges, OnDestroy, OnInit, Output, SimpleChanges } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { IconComponent } from '../../icon/icon.component';
import { MatCheckboxModule } from '@angular/material/checkbox';
import {
  bundleDetailRes,
  fileUpdateDetail,
  MYFILES_CONVERT_TYPE,
  MYFILES_CONVERSION_STATUS,
  MYFILES_SOCKET_CONVERTING_EVENT_LIST,
  MYFILES_SOCKET_CONVERTING_EVENTS,
  MYFILES_SOCKET_OCR_EVENTS,
} from '../../../interfaces/myfile.interface';
import { DragDropModule } from '@angular/cdk/drag-drop';
import { InputComponent } from '../../input/input.component';
import { MatMenuModule } from '@angular/material/menu';
import { MatTooltipModule } from '@angular/material/tooltip';
import { MyfileService } from '../../../services/myfile/myfile.service';
import { ButtonComponent } from '../../button/button.component';
import { TextFieldModule } from '@angular/cdk/text-field';
import { MatDialog } from '@angular/material/dialog';
import { CommonfunctionService } from '../../../../core/utility/commonfunction.service';
import { FacttableComponent } from '../facttable/facttable.component';
import { FactlinktableComponent } from '../factlinktable/factlinktable.component';
import { WeblinktableComponent } from '../weblinktable/weblinktable.component';
import { SocketService } from '../../../../core/services/socket/socket.service';
import { Subscription } from 'rxjs';
import { CommunicationService } from '../../../services/communication/communication.service';
import { AvatarComponent } from '../../avatar/avatar.component';
import { presentDocType } from '../../../../presentation/interfaces/presentsetup';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatSelectModule } from '@angular/material/select';
import { highlightModeType, myTeamUsers, toolEvents } from '../../../../pdf/interfaces/pdf.interface';
import { TruncateTooltipDirective } from '../../../directive/truncate-tooltip.directive';
import { OverflowCheckDirective } from '../../../directive/overflow-check.directive';
import { HyperLinkFolderComponent } from '../hyper-link-folder/hyper-link-folder.component';
import { TabletruncComponent } from '../tabletrunc/tabletrunc.component';
import { FilecolumnService } from '../../../services/filecolumn/filecolumn.service';
import { TranslateModule } from '@ngx-translate/core';
import { CommonService } from '../../../services/common/common.service';
@Component({
  selector: 'app-table',
  standalone: true,
  imports: [ScrollingModule, FormsModule, CommonModule, IconComponent, MatCheckboxModule, DragDropModule, InputComponent, MatMenuModule, MatTooltipModule,
    ButtonComponent, TextFieldModule, FacttableComponent, FactlinktableComponent, WeblinktableComponent, AvatarComponent,
    MatFormFieldModule, MatSelectModule, TruncateTooltipDirective, OverflowCheckDirective,
    TabletruncComponent,
    TranslateModule
  ],
  templateUrl: './table.component.html',
  styleUrl: './table.component.scss',
  providers: [MyfileService],
})
export class TableComponent implements OnInit, OnDestroy, OnChanges {
  private static readonly TEAM_USERS_MENU_PANEL_CLASS = 'team-users-menu-panel';
  private static readonly SHARE_MENU_OPEN_DELAY_MS = 0;
  private static readonly SHARE_MENU_CLOSE_DELAY_MS = 80;

  private static readonly teamUsersCache = new Map<string, myTeamUsers[]>();
  private static readonly teamUsersInFlight = new Map<string, Promise<myTeamUsers[]>>();

  @Input() isMyfile: boolean = false;
  @Output() changeTable: EventEmitter<string> = new EventEmitter();
  @Output() emitEvent: EventEmitter<toolEvents> = new EventEmitter();
  @Output() viewlink: EventEmitter<any> = new EventEmitter();
  @Input() col: any;
  @Input() filedetail: bundleDetailRes;
  @Input() changeF: boolean;
  @Input() changeB: boolean;
  @Input() disabledFiles: string[];
  @Input() isCopy: boolean;
  @Input() nCaseid: string;
  @Input() nSectionid: string;
  linkview: any = '';
  @Input() index: number;
  @Input() nohover: boolean = false;
  @Input() checkoutside: boolean = false;
  @Input() isIndividual: boolean = false;
  @Input() isShared: boolean = false;
  @Input() cutCopyType: string;
  @Input() cFoldertype: string;
  @Input() enableFileDrag: boolean = false;
  @Input() isLink: highlightModeType = null;
  items = [
    { template: 'template1', data: { name: 'John Doe' } },
    { template: 'template2', data: { age: 30 } }
  ];
  editname: boolean;
  isChange: boolean = false;
  clickfromcheckboc: boolean = false;

  isDisabled: boolean = false;
  flink: any = [];
  dlink: any = [];
  wlink: any = [];
  factlst: any = [];
  socketSubscription: Subscription;
  isOCR: boolean = false;
  OCRmessage = '';
  uploadedids: string[] = [];
  sharedUser: any[] = [];
  private evsubscription: Subscription;

  isCoreFile: boolean;
  @Input() presentDocType: presentDocType;
  @Input() coreFiles: string[] = [];

  @Input() bShowPresentHistory: boolean;

  @Input() reqcolKeys = [];

  @Input() isChooser: boolean = false;

  constructor(
    private readonly myfileS: MyfileService,
    private readonly cdr: ChangeDetectorRef,
    private readonly dialog: MatDialog,
    private readonly cf: CommonfunctionService,
    private readonly ss: SocketService,
    private readonly CMS: CommunicationService,
    private readonly fcs: FilecolumnService,
    private readonly common: CommonService,
  ) {
    this.socketSubscription = this.ss.getUploades().subscribe((res: any) => this.handleSocketMessage(res));
  }

  // share icon tooltip related methods removed

  // share icon tooltip: removed onShareMenuPanelMouseEnter and onShareMenuPanelMouseLeave

  private async ensureTeamUsersLoaded(): Promise<void> {
    const caseId = this.nCaseid;
    if (!caseId) {
      return;
    }

    const cached = TableComponent.teamUsersCache.get(caseId);
    if (cached != null) {
      // share icon tooltip: removed teamUsers assignment
      return;
    }

    // share icon tooltip: removed teamUsersLoading and detectChanges

    if (!TableComponent.teamUsersInFlight.has(caseId)) {
      const request = this.common.getMyTeamUsers(caseId)
        .then(list => list ?? [])
        .catch(() => []);
      TableComponent.teamUsersInFlight.set(caseId, request);
    }

    const request = TableComponent.teamUsersInFlight.get(caseId) ?? Promise.resolve<myTeamUsers[]>([]);
    const list = await request;
    TableComponent.teamUsersCache.set(caseId, list);
    TableComponent.teamUsersInFlight.delete(caseId);

    // share icon tooltip: removed teamUsers assignment and detectChanges
  }

  private handleSocketMessage(res: any): void {
    const event = res?.event;
    if (!event) {
      return;
    }

    if (this.handleConvertingEvents(event, res?.data)) {
      this.cdr.detectChanges();
      return;
    }

    if (this.handleOcrEvents(event, res)) {
      this.cdr.detectChanges();
    }
  }

  private handleConvertingEvents(event: string, data: any): boolean {
    if (!MYFILES_SOCKET_CONVERTING_EVENT_LIST.includes(event as any)) {
      return false;
    }

    const id = data?.identifier ?? data?.nBundledetailid;
    if (id == null || id !== this.filedetail?.nBundledetailid) {
      return true;
    }

    if (
      [
        MYFILES_SOCKET_CONVERTING_EVENTS.PROCESS,
        MYFILES_SOCKET_CONVERTING_EVENTS.START,
        MYFILES_SOCKET_CONVERTING_EVENTS.SUCCESS,
      ].includes(event as any) ||
      data?.cStatus === MYFILES_CONVERSION_STATUS.PROCESSING
    ) {
      this.filedetail.cCStatus = MYFILES_CONVERSION_STATUS.PROCESSING;
      this.filedetail.bIsconvert = true;
      return true;
    }

    if (data?.cStatus === MYFILES_CONVERSION_STATUS.INSERTING) {
      this.filedetail.cCStatus = MYFILES_CONVERSION_STATUS.INSERTING;
      this.filedetail.bIsconvert = true;
      return true;
    }

    if (event === MYFILES_SOCKET_CONVERTING_EVENTS.VERIFY_COMPLETE) {
      this.filedetail.cCStatus = MYFILES_CONVERSION_STATUS.VERIFY_SUCCESS;
      this.filedetail.bIsconvert = true;
      return true;
    }

    if ([MYFILES_SOCKET_CONVERTING_EVENTS.ERROR, MYFILES_SOCKET_CONVERTING_EVENTS.FAILED].includes(event as any)) {
      this.filedetail.cCStatus = MYFILES_CONVERSION_STATUS.FAILED;
      this.filedetail.bIsconvert = false;
      return true;
    }

    if (event === MYFILES_SOCKET_CONVERTING_EVENTS.FILE_INSERT_COMPLETE) {
      this.filedetail.cCStatus = MYFILES_CONVERSION_STATUS.SUCCESS;
      if (data?.converttype === MYFILES_CONVERT_TYPE.CONVERT) {
        this.filedetail.bIsconvert = false;
        this.filedetail.cFiletype = data?.cFiletype;
        this.filedetail.cName = data?.cFilename;
        this.filedetail.cPage = data?.cPage;
      }
      return true;
    }

    return true;
  }

  private handleOcrEvents(event: string, res: any): boolean {
    const fileId = this.filedetail?.nBundledetailid;

    if (event === MYFILES_SOCKET_OCR_EVENTS.START) {
      if (res?.id && res?.data?.id === fileId) {
        this.isOCR = true;
        return true;
      }
      return false;
    }

    if (event === MYFILES_SOCKET_OCR_EVENTS.PROGRESS) {
      if (res?.data?.id === fileId) {
        this.isOCR = true;
        this.OCRmessage = res?.data?.message ?? '';
        return true;
      }
      return false;
    }

    if (event === MYFILES_SOCKET_OCR_EVENTS.SUCCESS || event === MYFILES_SOCKET_OCR_EVENTS.ERROR) {
      if (res?.data?.id === fileId) {
        this.isOCR = false;
        this.OCRmessage = '';
        return true;
      }
      return false;
    }

    return false;
  }

  checkForIsCore(): void {
    if (this.presentDocType === 'C' || this.presentDocType === 'CF') {
      this.isCoreFile = !!this.coreFiles?.includes(this.filedetail?.nBundledetailid);
    }

    this.cdr.detectChanges();
  }

  ngOnInit(): void {
    if (this.disabledFiles?.length) {
      this.isDisabled = this.disabledFiles.includes(this.filedetail?.nBundledetailid);
    }

    this.checkForIsCore();

    this.checkEventSub();
    if (!this.reqcolKeys?.length) {
      Object.fromEntries(
        Object.entries(this.fcs.reqcols).filter(([key]) => {
          let cols = this.fcs.tablecols.find(e => e.key.toLocaleLowerCase() == key)
          if (cols) {
            this.fcs.reqcols[key]["id"] = cols?.id;
            this.fcs.reqcols[key]["view"] = cols?.isshow;
            this.fcs.reqcols[key]["name"] = cols?.name;
            this.fcs.reqcols[key]["class"] = cols?.class;
            this.fcs.reqcols[key]["sortKey"] = cols?.sortKey;
            this.fcs.reqcols[key]["isEdit"] = cols?.isEdit;
            this.fcs.reqcols[key]["size"] = cols?.size;
          }
        })
      )
      this.col = Object.fromEntries(
        Object.entries(this.fcs.reqcols).filter(([key]) => key !== 'relevence' && key !== 'link' && key !== 'impact')
      )

      this.reqcolKeys = Object.keys(this.col);
      this.reqcolKeys = this.fcs.customSort(this.col)
    }
  }
  ngOnDestroy(): void {
    this.evsubscription?.unsubscribe();
    this.socketSubscription?.unsubscribe();
  }

  checkEventSub(): void {
    this.evsubscription = this.CMS.functionCalled$.subscribe((data) => {
      if (data?.event === 'SELECT-FILE') {
        this.uploadedids = data.nBundledetailids;
        this.isSelected();
        this.checkForIsCore();
        this.cdr.detectChanges();
      }
    })
  }


  ngOnChanges(changes: SimpleChanges): void {
    if (changes['filedetail'] && !changes['filedetail'].firstChange) {
      if (this.disabledFiles?.length) {
        this.isDisabled = this.disabledFiles.includes(this.filedetail?.nBundledetailid);
      }
    }

    if (changes['changeB']) {
      this.col['bundle']['edit'] = false
    }

    this.isConvertallow();
    this.checkForIsCore();
    this.cdr.detectChanges();
  }

  openFolder() {
    this.emitEvent.emit({ event: 'OPEN_FOLDER', data: { nBundleid: this.filedetail.nBundleid, cName: this.filedetail.cName } })
  }

  checkFile(event) {
    this.clickfromcheckboc = true;
    this.filedetail.cIscheck = event.checked;
    this.emitEvent.emit({ event: 'SELECTED', data: { cIscheck: this.filedetail.cIscheck } })
    setTimeout(() => {
      this.clickfromcheckboc = false
    }, 100);
  }

  changeBundle(bundle) {
    this.changeTable.emit('EDIT_BUNDLE_' + bundle)
  }

  async updateFileData(x, el, event?) {
    if (!this.isChange) { return };
    this.isChange = false
    const mdl: fileUpdateDetail = {
      nBundledetailid: x.nBundledetailid,
      cTab: (x.cTab ?? '').trim(),
      cExhibitno: (x.cExhibitno ?? '').trim(),
      cFilename: (x.cName ?? '').trim(),
      cDescription: (x.cDescription ?? '').trim(),
      dIntrestDt: (x.dIntrestDt ?? '').trim(),
      cAuthor: (x.cAuthor ?? '').trim()
    };
    const res: boolean = await this.myfileS.updateBundle(mdl);
    if (res) {
      if (event) (event.input.nativeElement.blur())
    };
    this.cdr.detectChanges();
  }

  async updateFoldername(x) {
    const mdl = {
      nBundleid: x.nBundleid,
      nParentBundleid: x.nParentBundleid || null,
      nCaseid: this.nCaseid,
      nSectionid: this.nSectionid || null,
      cBundlename: x.cName,
      permission: 'E'
    };

    let res = await this.myfileS.bundleBuilder(mdl);
    if (res) {
      this.editname = false;
      this.changeTable.emit('RENAME-BUNDLE');
    }

  }

  async updateTabRef(x) {
    this.changeTable.emit('EDIT_TAB_' + (x.cTab ? x.cTab : '').trim())
  }

  getPermission() {
    this.changeTable.emit('PERMISSION')
  }

  getShare() {
    this.changeTable.emit('SHARE')
  }

  deleteBundleReq() {
    this.changeTable.emit('DELETE');
  }

  clickTimeout: any;

  viewFileDB(event) {
    clearTimeout(this.clickTimeout);
    const pageRange = this.filedetail?.cPageRange;
    const startPageText = pageRange?.split('-')?.[0] ?? '';
    const parsed = Number.parseInt(startPageText, 10);
    const nPage = Number.isFinite(parsed) ? parsed : 1;

    if (this.isLink) {
      this.changeTable.emit('VIEW');
      return;
    }

    if (this.isMyfile) {
      this.cf.openHyperLinkFile(this.filedetail.nBundledetailid, this.nCaseid, null, null, this.filedetail.cIsindex, nPage)
      return;
    }

    this.openDocumentInChooser(this.filedetail)
  }

  async openDocumentInChooser(x) {
    this.emitEvent.emit({ event: 'OPEN-DOCUMENT', data: { nBundledetailid: x.nBundledetailid } });
  }

  viewFile(event) {
    clearTimeout(this.clickTimeout);
    this.clickTimeout = setTimeout(() => {

      if (this.uploadedids.length) {
        let indx = this.uploadedids.findIndex(e => e == this.filedetail.nBundledetailid);
        if (indx > -1) {
          this.uploadedids.splice(indx, 1)
        }
      }
      if (this.clickfromcheckboc) return;
      if (this.isDisabled) return;
      this.changeTable.emit('VIEW');
    }, 250);

  }

  HyperLinkFile(mode: string, type: 'K' | 'R', isDeep?: boolean) {
    this.viewlink.emit({ "event": 'HYPERLINK', nBundledetailid: this.filedetail.nBundledetailid, mode: mode, cKeeptype: type, cIsindex: this.filedetail.cIsindex, isDeep: isDeep });
  }

  dragStarted(event) {
    this.changeTable.emit('DRAG-START');
  }

  pagination(x) {
    this.changeTable.emit('PAGINATION')
  }

  isUpdate_batchprocess(x) {
    return this.filedetail?.updateCols?.includes(x.dbkey) ?? false;
  }

  isSelected(): boolean {
    const fileId = this.filedetail?.nBundledetailid;
    return !!(
      this.cf.viewlist?.some(e => e.nBundledetailid == fileId) ||
      this.uploadedids?.includes(fileId)
    );
  }

  checkTruncate(parent: HTMLElement, child: HTMLElement) {
    if (child.offsetWidth > parent.offsetWidth) {
      child.classList.add('truncated');
    } else {
      child.classList.remove('truncated');
    }
  }

  async viewLink(flag): Promise<void> {
    if (this.filedetail?.linkview == flag) {
      this.filedetail.linkview = '';
      this.emitEvent.emit({ event: 'VIEW-LINK', data: { linkview: '' } });
      this.cdr.detectChanges();
      return
    }

    this.filedetail.linkview = this.filedetail?.linkview == flag ? '' : flag;

    if (flag == 'F') {
      this.viewlink.emit({ "event": 'VIEWFACT', data: '' });
    } else if (flag == 'QF') {
      this.viewlink.emit({ "event": 'VIEWQFACT', data: '' });
    }

    const fileId = this.filedetail?.nBundledetailid;
    if (!fileId) {
      return;
    }

    if (['DL', 'WL', 'FL', 'F', 'QF'].includes(flag)) {
      const res = await this.myfileS.getFilelinks(fileId, flag)
      const first = res?.[0];
      if (flag == 'DL') {
        this.filedetail.dlink = first;
      } else if (flag == 'WL') {
        this.filedetail.wlink = first;
      } else {
        this.filedetail.flinklst = first;
      }
    }

    this.cdr.detectChanges();
  }

  isConvertallow() {
    let type = this.filedetail.cFiletype;
    if (type && ['doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx', 'jpg', 'jpeg', 'png', 'bmp', 'gif', 'tiff', 'zip', 'msg']?.includes((type).toLowerCase())) {
      this.filedetail.bIsconvert = true;
      return
    }
    this.filedetail.bIsconvert = false;
  }

  convertBundleReq(event) {
    this.myfileS.convertFile(this.filedetail.nBundledetailid, this.nCaseid).then(res => {
      if (res) {
        this.filedetail.bIsconvert = false;
        this.cdr.detectChanges();
      }
    })
  }

  ocrFileReq(nOcrtype) {
    this.isOCR = true;
    this.myfileS.ocrFile(this.filedetail.nBundledetailid, nOcrtype).then(res => {
      if (res) {
        this.filedetail.bIsconvert = false;
        this.cdr.detectChanges();
      }
    })
  }

  viewSharedUser(sh) {
    if (this.filedetail?.share) {
      if (!this.sharedUser?.length) {
        this.myfileS.getSharedUser(this.filedetail.nBundledetailid).then(res => {
          if (res) {
            sh.openMenu();
            this.sharedUser = res;
            this.cdr.detectChanges();
          }
        })
        return;
      }
      sh.openMenu();
    }
  }

  SelectCore(menu) {
    this.isCoreFile = !this.isCoreFile
    if (this.isCoreFile) {
      menu.openMenu();
      setTimeout(() => {
        menu.closeMenu();
      }, 3000);
      if (!this.coreFiles?.includes(this.filedetail.nBundledetailid)) {
        this.coreFiles.push(this.filedetail.nBundledetailid);
      }
    } else {
      const ind = this.coreFiles.findIndex(e => e == this.filedetail.nBundledetailid);
      this.coreFiles.splice(ind, 1);
      menu.closeMenu();
    }
    this.cdr.detectChanges()
  }

  viewlinkEvent(event) {
    this.viewlink.emit(event)
  }

  starFile(file: bundleDetailRes) {
    file.bIsStar = !file.bIsStar;
  }

  clicktruncate(elm) {
    let elmclone = elm.cloneNode(true);
    let parent = elm.parentElement;
    elmclone.style.width = 'fit-content';
    elmclone.style.position = 'absolute';
    elmclone.style.visibility = 'hidden';
    elmclone.style.whiteSpace = 'nowrap';
    parent.appendChild(elmclone);
    if (elmclone.clientWidth > parent.clientWidth) {
      elmclone.remove();
      return true;
    }

    return false;
  }

  viewFileEvent(event) {
    this.changeTable.emit(event);
  }

  hyperlink(filedetail) {
    const dialogRef = this.dialog.open(HyperLinkFolderComponent, {
      width: '596px',
      height: 'fit-content',
      panelClass: ['addusermodal', 'rounded-10', 'overflow-hidden'],
      data: {
        cName: filedetail.cName,
      }
    });
    dialogRef.afterClosed().subscribe(result => {
      if (result) {
        this.HyperLinkFile(result.linkType, result.type, result.isDeep);
      }
    });
  }
}